args<-commandArgs(trailingOnly=TRUE);if(length(args)<3)stop("Usage: train_rsf.R <dev.csv> <val.csv> <out> [vars] [seed]");if(!requireNamespace("randomForestSRC",quietly=TRUE)||!requireNamespace("survival",quietly=TRUE))stop("Install randomForestSRC and survival")
tr<-read.csv(args[1],check.names=FALSE);va<-read.csv(args[2],check.names=FALSE);out<-args[3];vars<-if(length(args)>=4)strsplit(args[4],",",fixed=TRUE)[[1]]else setdiff(names(tr),c("Time","Event"));seed<-if(length(args)>=5)as.integer(args[5])else 123L;dir.create(out,recursive=TRUE,showWarnings=FALSE);f<-as.formula(paste("survival::Surv(Time,Event)~",paste(vars,collapse="+")))
set.seed(seed);fit<-randomForestSRC::rfsrc(f,tr[,c("Time","Event",vars)],ntree=1000,nodesize=3,mtry=max(1,floor(sqrt(length(vars)))),splitrule="logrank",importance=TRUE,forest=TRUE)
pred<-function(d,set){p<-predict(fit,newdata=d[,vars,drop=FALSE]);write.csv(data.frame(Time=d$Time,Event=d$Event,RSF=as.numeric(p$predicted)),file.path(out,paste0(set,"_rsf_predictions.csv")),row.names=FALSE)};pred(tr,"development");pred(va,"validation")
write.csv(data.frame(variable=names(fit$importance),importance=as.numeric(fit$importance)),file.path(out,"rsf_importance.csv"),row.names=FALSE);saveRDS(fit,file.path(out,"rsf_model.rds"))
